/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        top_bg: cc.Node,
        items: [cc.Node],
        black_bg: cc.Node,

        _haveOpenReward:[],
        _canSelect: true,
        _result: null,
        _successCallback: null,
        _unlockBooster: [],
    },

    onLoad () {

    },

    async enterPickGame(index, times, pickBoosterGame) {
        return new Promise((success)=>{
            this._successCallback = success;
            this.node.active = true;
            this.reset();

            for (let i = 0; i < pickBoosterGame.choiceIdxs.length; i++) {
                let index = pickBoosterGame.choiceIdxs[i];
                let item = cc.find("item_bg/item_" + index, this.node);
                this.showReward(item, false, pickBoosterGame.choiceItems[i]);
                this._haveOpenReward.push(index);
            }

            cc.find("num_2", this.top_bg).active = pickBoosterGame.totalCnt === 2;
            cc.find("num_3", this.top_bg).active = pickBoosterGame.totalCnt === 3;

            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("pick2_bgm");

            for (let i = 1; i < 9; i++) {
                let item = cc.find("item_bg/item_" + i, this.node);
                item.off(cc.Node.EventType.TOUCH_END);
                item.on(cc.Node.EventType.TOUCH_END, ()=>{
                    if (!this._canSelect) {
                        return;
                    }
                    item.off(cc.Node.EventType.TOUCH_END);

                    cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "mappick_open", true);
                    this._canSelect = false;
                    let req = {c: MsgId.SLOT_SUBGAME_DATA};
                    req.uid = Global.playerData.uid;
                    req.gameid = cc.vv.gameData._gameId;
                    req.data = {};
                    req.data.rtype = 1;
                    req.data.choiceId = i;
                    cc.vv.NetManager.send(req);
                });
            }
        });

    },

    reset() {
        this._haveOpenReward = [];
        this._result = null;
        this._canSelect = true;
        this._unlockBooster = [];
        for (let i = 1; i < 9; i++) {
            let item = cc.find("item_bg/item_" + i, this.node);
            for (let child of item.children) {
                child.color = cc.Color.WHITE;
            }
            let spine = cc.find("spine", item).getComponent(sp.Skeleton);
            spine.setAnimation(0, "animation", true);

            let coin = cc.find("coin", item);
            coin.active = false;

            let coin_light = cc.find("coin_light", item);
            coin_light.active = false;
        }
    },

    async onRcvSubGameData(msg) {
        if (msg.code !== 200) {
            this._canSelect = true;
            return;
        }

        if (msg.data.rtype !== 1) {
            this._canSelect = true;
            return;
        }

        let cfg = cc.vv.gameData.getGameCfg();
        let data = msg.data;
        this._result = data;
        this._haveOpenReward.push(data.choiceId);
        if (data.choiceItem.type !== cfg.MapBoostType.Coin) {
            this._unlockBooster.push(data.choiceItem.type);
        }
        if (data.pickBoosterGame.isEnd) {
            // 结束了
            let item = this.items[data.choiceId - 1];
            this.showReward(item, false, data.choiceItem);

            await cc.vv.gameData.awaitTime(0.8);

            cc.vv.gameData.AddCoin(data.pickBoosterGame.winCoin);

            // cc.vv.AudioManager.playEff("games/SpookyHalloween/", "pick_end", true);

            let resultIndex = 0;
            for (let i = 0; i < this.items.length; i++) {
                if (this._haveOpenReward.indexOf(i + 1) === -1) {
                    let item = this.items[i];
                    this.showReward(item, true, data.pickBoosterGame.totalItems[resultIndex]);
                    resultIndex++;
                }
            }

            await cc.vv.gameData.awaitTime(2);

            await this.popResult();

            this._successCallback();
        } else {
            // 没结束
            this._canSelect = true;
            let item = this.items[data.choiceId - 1];
            this.showReward(item, false, data.choiceItem);
        }
    },

    getResult() {
        return this._result;
    },

    async showReward(item, isGray, reward) {
        let cfg = cc.vv.gameData.getGameCfg();
        let animationIndex = 1;
        switch (reward.type) {
            case cfg.MapBoostType.ExtraFreeCnt:
                animationIndex = 2;
                break;
            case cfg.MapBoostType.WildPaysDouble:
                animationIndex = 6;
                break;
            case cfg.MapBoostType.Coin:
                animationIndex = 7;
                break;
            default:
                animationIndex = reward.type;
                break;
        }

        let spine = item.getChildByName("spine").getComponent(sp.Skeleton);
        if (isGray) {
            spine.setAnimation(0, "animation" + animationIndex + "_2", false);
            for (let child of item.children) {
                child.color = cc.Color.GRAY;
            }
            if (reward.type === cfg.MapBoostType.Coin) {
                let coin = cc.find("coin", item);
                coin.active = true;
                coin.scale = 1;
                coin.getComponent(cc.Label).string = Global.formatNumShort(reward.coin, 0);
            }
        } else {
            spine.setAnimation(0, "animation" + animationIndex, false);
            spine.addAnimation(0, "animation" + animationIndex + "_1", true);

            if (reward.type === cfg.MapBoostType.Coin) {
                let coin = cc.find("coin", item);
                coin.getComponent(cc.Label).string = Global.formatNumShort(reward.coin, 0);
                coin.active = true;
                coin.scale = 0;
                cc.tween(coin)
                    .delay(0.3)
                    .to(0.5, {scale: 1}, {easing: "backOut"})
                    .call(()=>{
                        cc.find("coin_light", item).active = true;
                    })
                    .start();
            }
        }
    },

    async popResult() {
        return new Promise(async (success)=>{
            let cfg = cc.vv.gameData.getGameCfg();
            if (this._result) {
                let boosterNum = 0;
                for (let item of this._result.pickBoosterGame.choiceItems) {
                    if (item.type !== cfg.MapBoostType.Coin) {
                        boosterNum++;
                    }
                }

                cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "dialog_mappick_collect", true);

                this.black_bg.active = true;
                let node = cc.find("booster_result_" + boosterNum, this.node);
                node.active = true;
                let spine = node.getComponent(sp.Skeleton);
                if (boosterNum === 0) {
                    spine.setAnimation(0, "animation", false);
                    spine.addAnimation(0, "animation2", true);
                } else {
                    spine.setAnimation(0, "animation" + (boosterNum + 1) + "_1", false);
                    spine.addAnimation(0, "animation" + (boosterNum + 1) + "_2", true);
                }


                let coin = cc.find("coin", node);
                coin.scale = 0;
                Global.doRoallNumEff(coin, 0, this._result.pickBoosterGame.winCoin, 1.5, null, null, 0, true);
                cc.tween(coin)
                    .delay(0.2)
                    .to(0.5, {scale: 1}, {easing: "backOut"})
                    .start();

                let btn_collect = cc.find("btn_collect", node);
                btn_collect.scale = 0;
                cc.tween(btn_collect)
                    .delay(0.4)
                    .to(0.5, {scale: 0.5}, {easing: "backOut"})
                    .start();

                let booster_1 = cc.find("booster_1", node);
                if (booster_1) {
                    booster_1.scale = 0;
                    let atlas = cc.vv.gameData.GetAtlasByName("popup");
                    booster_1.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme205_pop_booster" + this._unlockBooster[0]);
                    cc.tween(booster_1)
                        .delay(0.3)
                        .to(0.5, {scale: boosterNum === 1 ? 1 : 0.8}, {easing: "backOut"})
                        .start();
                }

                let booster_2 = cc.find("booster_2", node);
                if (booster_2) {
                    let atlas = cc.vv.gameData.GetAtlasByName("popup");
                    booster_2.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme205_pop_booster" + this._unlockBooster[1]);
                    booster_2.scale = 0;
                    cc.tween(booster_2)
                        .delay(0.3)
                        .to(0.5, {scale: boosterNum === 1 ? 1 : 0.8}, {easing: "backOut"})
                        .start();
                }

                await cc.vv.gameData.awaitTime(0.9);

                let func = ()=>{
                    cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "click", true);

                    cc.vv.gameData.GetSlotsScript()._bottomScript.SetWin(this._result.pickBoosterGame.winCoin);

                    btn_collect.off("click");
                    cc.tween(coin)
                        .to(0.5, {scale: 0}, {easing: "backIn"})
                        .start();

                    cc.tween(btn_collect)
                        .to(0.5, {scale: 0}, {easing: "backIn"})
                        .start();

                    if (booster_1) {
                        cc.tween(booster_1)
                            .to(0.5, {scale: 0}, {easing: "backOut"})
                            .start();
                    }

                    if (booster_2) {
                        cc.tween(booster_2)
                            .to(0.5, {scale: 0}, {easing: "backOut"})
                            .start();
                    }

                    if (boosterNum === 0) {
                        spine.setAnimation(0, "animation3", false);
                    } else {
                        spine.setAnimation(0, "animation" + (boosterNum + 1) + "_3", false);
                    }
                    spine.setCompleteListener(()=>{
                        spine.setCompleteListener(null);
                        this.black_bg.active = false;
                        success();
                    })
                }
                cc.vv.gameData.checkAutoPlay(btn_collect, func)

                btn_collect.on("click", ()=>{
                    btn_collect.stopAllActions();
                    func();
                });
            }
        });
    },
});