/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {},

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},
    Init: function (idx, node) {
        this._super(idx, node);

        this._showNode.color = cc.Color.WHITE;
    },


    StartMove: function () {
        this._super();
        if (this._id !== cc.vv.gameData.getGameCfg().bonusId) {
            this._showNode.color = cc.Color.GRAY;
        } else {
            this._showNode.color = cc.Color.WHITE;
        }
    },

    //显示随机符号
    ShowRandomSymbol: function () {
        this._super();

        if (this._id !== cc.vv.gameData.getGameCfg().bonusId) {
            this._showNode.color = cc.Color.GRAY;
        } else {
            this._showNode.color = cc.Color.WHITE;
        }
        this.showCoin();
        this.showFreeTimes();
    },

    ShowById(id, data) {
        this._super(id, data);
        this.showCoin();
        this.showFreeTimes();
    },

    playStopAnimation(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani){
            this._state = "stop";
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            if(cfg.symbol[id].stop_ani.name !== ""){
                this.node.zIndex = cfg.symbol[id].stop_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].stop_ani.name,false)
                    if (id === cfg.bonusId) {
                        nodeSp.addAnimation(0, cfg.symbol[id].idle_ani.name, true);
                    }
                }
            }
        }
    },

    showCoin() {
        let coin = cc.find("coin", this.node);
        let jackpot = cc.find("jackpot", this.node);
        if (coin && jackpot && this._id === cc.vv.gameData.getGameCfg().bonusId) {
            if (this._data) {
                if (this._data.coin > 0) {
                    coin.active = true;
                    coin.getComponent(cc.Label).string = Global.formatNumShort(this._data.coin, 0);
                } else if (this._data.jackpot) {
                    jackpot.active = true;
                    let atlas = cc.vv.gameData.GetAtlasByName("symbols");
                    jackpot.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme205_s_jp" + (5 - this._data.jackpot.id));
                }
            } else if (cc.vv.gameData.GetSlotsScript().getBaseCoin() !== 0) {
                coin.active = true;
                coin.getComponent(cc.Label).string = Global.formatNumShort(cc.vv.gameData.GetSlotsScript().getBaseCoin(), 0);
            } else {
                coin.active = true;
                let randomRate = [0.25, 0.5, 0.75, 1, 2, 5, 10];
                let randomCoin = cc.vv.gameData.GetTotalBet() * randomRate[Math.floor(Math.random() * randomRate.length)];
                coin.getComponent(cc.Label).string = Global.formatNumShort(randomCoin, 0);
            }
        } else {
            coin.active = false;
            jackpot.active = false;
        }
    },

    showFreeTimes() {
        let times = cc.find("times", this.node);
        if (times && this._id === cc.vv.gameData.getGameCfg().extraSpinId) {
            if (this._data && this._data.freeCnt) {
                times.active = true;
                times.getComponent(cc.Label).string = this._data.freeCnt;
            }
        } else {
            times.active = false;
        }
    },

    //赢钱动画
    playWinAnimation(){
        if(this._showNode){
            this._showNode.active = false
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node){
            this._state = "win";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].win_ani && cfg.symbol[id].win_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].win_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    if (id === cfg.extraSpinId) {
                        if (this._data.freeCnt > 1) {
                            nodeSp.setAnimation(0,cfg.symbol[id].win_ani.name,true)
                        } else {
                            nodeSp.setAnimation(0,cfg.symbol[id].win_ani_1.name,true)
                        }
                    } else {
                        nodeSp.setAnimation(0,cfg.symbol[id].win_ani.name,true)
                    }
                }
            }
        }
        else{
            //如果没有中奖动画，先显示出来
            //TODO：后续补充一个没有spin动画的显示效果
            this._showNode.active = true
            this.playWinTweenAction()
        }
    },

    playTriggerAnimation() {
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani) {
            this._state = "trigger";
            if (this._showNode) {
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node, aniNode)
            topShowNode.active = true
            if (cfg.symbol[id].trigger_ani.name !== "") {
                aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if (nodeSp) {
                    nodeSp.setAnimation(0, cfg.symbol[id].trigger_ani.name, false)
                    if ((id === cfg.scatterId || id === cfg.bonusId) && cfg.symbol[id].idle_ani) {
                        nodeSp.setCompleteListener(() => {
                            nodeSp.setCompleteListener(null);
                            nodeSp.setAnimation(0, cfg.symbol[id].idle_ani.name, true);
                            if (cc.find("icon", topShowNode)) {
                                cc.find("icon", topShowNode).active = true;
                            }
                        })

                    }
                }
            }
        }
        return isPlay
    },

    playFlyBonusAnimation() {
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()

            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

                this.node.zIndex = 500 - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,"animation1_5",false)
                }


    },

    playWildAnimation() {
        if (this._showNode) {
            this._showNode.active = false
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (cfg.symbol[id] && cfg.symbol[id].win_node) {
            this._state = "win";
            if (this._showNode) {
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node, aniNode)
            topShowNode.active = true

            aniNode.zIndex = 300 - this._symbolIdx + this._reelIdx * 10;
            let nodeSp = topShowNode.getComponent(sp.Skeleton);
            let animationName = id === 105 ? "animation1_1" : "animation1";
            if (this._symbolIdx < cc.vv.gameData.getGameCfg().row && this._symbolIdx > 0) {
                animationName = "animation" + (5 + (3 - this._symbolIdx)) + (id === 105 ? "_1" : "");
            }
            if (nodeSp) {
                nodeSp.setAnimation(0, animationName, true)
            }
        }
    },

    Resume(backup) {
        if (!backup) return;
        this._symbolIdx = backup.symbolIdx;
        this._id = backup.id;
        this._data = Global.copy(backup.data);
        this.ShowKuang(backup.isKuang);
        this.ShowNormal();
        let cfg = cc.vv.gameData.getGameCfg();
        let state = backup.state;
        if (state == "win") {
            if (this.GetShowId() === 101 ||
                this.GetShowId() === 102 ||
                this.GetShowId() === 103) {
                if (Math.floor((Number(key) - 1) / cfg.col) === (cfg.row - 1)) {
                    // 101 102 103 只有在最后一行才播放动画
                    this.playWinAnimation();
                } else {
                    let col = this.GetSymbolReelIdx();
                    let reel = cc.vv.gameData.GetSlotsScript()._reels[col];
                    for (let i = 0; i < cfg.row; i++) {
                        let newSymbol = reel.GetSymbolByRow(i);
                        if (newSymbol.GetShowId() === 104 ||
                            newSymbol.GetShowId() === 105
                        ) {
                            newSymbol.playWildAnimation();
                            break;
                        } else if (newSymbol.GetShowId() === 101 ||
                            newSymbol.GetShowId() === 102 ||
                            newSymbol.GetShowId() === 103) {
                            newSymbol.playWinAnimation();
                            break;
                        }
                    }
                }
            } else {
                this.playWildAnimation();
            }
        } else if (state == "stop") {
            this.playStopAnimation();
        } else if (state == "idle") {
            this.playidleAnimation();
        } else if (state == "trigger") {
            this.playTriggerAnimation();
        }

        if (this._id === cfg.bonusId || this._id === cfg.extraSpinId) {
            this._state = "win";
            this.playWinAnimation();
        }
    },

    resetColor() {
        this._showNode.color = cc.Color.WHITE;
    },
});