/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_PrizePool_Base"),
    properties: {

    },

    ShowNodeLockByNode:function(node,bLock,unLockBet,poolType,bInit) {
        if (node) {
            let lockNode = cc.find("lock", node);
            let lockTips = cc.find("image", lockNode);
            let unlockNode = cc.find("unlock", node);
            let unlockTips = cc.find("image", unlockNode);
            let spine = cc.find("jpsuo", node).getComponent(sp.Skeleton);

            if (bLock) {
                if (bInit) {
                    lockNode.active = true;
                    spine.setAnimation(0, "animation" + (4 - poolType) + "_2", true);
                    unlockNode.active = false;
                    lockTips.scale = 0;
                } else {
                    cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "jp_lock", true);
                    spine.clearTracks();
                    spine.setToSetupPose();
                    spine.setAnimation(0, "animation" + (4 - poolType), false);
                    spine.addAnimation(0, "animation" + (4 - poolType) + "_2", true);

                    lockNode.active = true;
                    unlockNode.active = false;
                    lockTips.scale = 0;
                    cc.tween(lockTips)
                        .to(0.1, {scale: 1}, {easing: "backOut"})
                        .delay(2)
                        .to(0.1, {scale: 0}, {easing: "backIn"})
                        .start();
                }
            } else {
                if (bInit) {
                    lockNode.active = false;
                    unlockNode.active = true;
                    unlockTips.scale = 0;
                    spine.setAnimation(0, "animation", true);
                } else {
                    cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "jp_unlock", true);
                    spine.clearTracks();
                    spine.setToSetupPose();
                    spine.setAnimation(0, "animation" + (4 - poolType) + "_1", false);
                    spine.addAnimation(0, "animation", true);

                    lockNode.active = false;
                    unlockNode.active = true;
                    unlockTips.scale = 0;
                    cc.tween(unlockTips)
                        .to(0.1, {scale: 1}, {easing: "backOut"})
                        .delay(2)
                        .to(0.1, {scale: 0}, {easing: "backIn"})
                        .start();
                }
            }
        }
    },
});