            freetanchuang_spine.node.active = true;

            let coin = cc.find("coin", dialog);
            coin.getComponent(cc.Label).string = Global.formatNumShort(this._gameInfo.bonusBaseCoin, 0);
            cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "dialog_fg_start", true);

