    async updateCollectProgress(mapInfo, isAdd) {
        let progress = cc.find("collect_node/progress", this.node);
        let scale_node = cc.find("collect_node/scale_node", this.node);
        if (isAdd) {
            cc.tween(scale_node)
                .to(0.3, {
                    scaleX: (mapInfo.progressData.totalCnt / mapInfo.progressData.needCnt > 1 ?
                        1 : mapInfo.progressData.totalCnt / mapInfo.progressData.needCnt)
                })
                .start();

            cc.tween(progress.getComponent(cc.ProgressBar))
                .to(0.3, {
                    progress: mapInfo.progressData.totalCnt / mapInfo.progressData.needCnt > 1 ?
                        1 : mapInfo.progressData.totalCnt / mapInfo.progressData.needCnt
                })
                .start();

            let spine_collect = cc.find("bar/jdtshangzhang", progress).getComponent(sp.Skeleton);
            spine_collect.node.active = true;
            spine_collect.setToSetupPose();
            spine_collect.setAnimation(0, "animation", false);
            spine_collect.setCompleteListener(() => {
                spine_collect.node.active = false;
            });
        } else {
            progress.getComponent(cc.ProgressBar).progress = mapInfo.progressData.totalCnt / mapInfo.progressData.needCnt > 1 ?
                1 : mapInfo.progressData.totalCnt / mapInfo.progressData.needCnt;
            scale_node.scaleX = mapInfo.progressData.totalCnt / mapInfo.progressData.needCnt > 1 ?
                1 : mapInfo.progressData.totalCnt / mapInfo.progressData.needCnt;
        }
    },

    clearCollectProgress() {
        let progress = cc.find("collect_node/progress", this.node);
        let scale_node = cc.find("collect_node/scale_node", this.node);
        scale_node.scaleX = 0;
        progress.getComponent(cc.ProgressBar).progress = 0;
    },
