/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        reels_bg: cc.Node,
        tips_node: cc.Node,
        reels_frame: cc.Node,
        bonus_bj: sp.Skeleton,
        bonus_wenzi: sp.Skeleton,
        items_node: cc.Node,
        items: [cc.Node],
        pick_lizi: cc.Node,
        tengman: sp.Skeleton,
        remain_times: cc.Label,

        _successCallback: null,
        _canSelect: false,
        _remainTimes: 3,
        _haveOpenReward: [],
        _winCoin: 0,
        _startPosY: 0,
    },

    onLoad() {

    },

    async reconnect() {
        return new Promise((success)=>{
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("pick1_bgm");

            this.reset();
            this._successCallback = success;

            this.node.active = true;

            let pickBonus = cc.vv.gameData.getDeskInfo().pickBonus;
            this._remainTimes = pickBonus.spinCnt;

            this.bonus_bj.node.active = true;
            this.bonus_bj.setAnimation(0, "animation1_2", true);

            this.bonus_wenzi.node.y = 0;
            this.bonus_wenzi.node.active = true;
            this.bonus_wenzi.setAnimation(0, "animation2", true);

            this.reels_bg.active = true;
            this.reels_frame.active = true;

            this.items_node.active = true;

            this._haveOpenReward = pickBonus.choiceIdxs;

            this._canSelect = true;

            for (let i = 0; i < this.items.length; i++) {
                let item = this.items[i];
                item.scale = 1;
                item.off(cc.Node.EventType.TOUCH_END);
                item.on(cc.Node.EventType.TOUCH_END, () => {
                    if (!this._canSelect) {
                        return;
                    }
                    item.off(cc.Node.EventType.TOUCH_END);

                    cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "pick_click", true);
                    this._canSelect = false;
                    let req = {c: MsgId.SLOT_SUBGAME_DATA};
                    req.uid = Global.playerData.uid;
                    req.gameid = cc.vv.gameData._gameId;
                    req.data = {};
                    req.data.rtype = 2;
                    req.data.choiceId = i + 1;
                    cc.vv.NetManager.send(req);
                });
                cc.find("zishuijing", item).getComponent(sp.Skeleton).setAnimation(0, "animation2", true);
                if (this._haveOpenReward.indexOf(i + 1) !== -1) {
                    let lanbaoshi_spine = cc.find("lanbaoshi", item).getComponent(sp.Skeleton);
                    lanbaoshi_spine.node.active = true;
                    lanbaoshi_spine.setAnimation(0, "animation1", true);

                    let reward = pickBonus.items[i];
                    if (reward.coin > 0) {
                        let coin = cc.find("coin", item);
                        coin.active = true;
                        coin.getComponent(cc.Label).string = Global.formatNumShort(reward.coin, 0);
                    } else {
                        let atlas = cc.vv.gameData.GetAtlasByName("symbols");
                        cc.find("jackpot", item).active = true;
                        cc.find("jackpot", item).getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme205_s_jp" + (5 - reward.jackpot.id));
                    }
                }
            }

            cc.find("collect_node", this.node.parent).y -= 100;
            this.tips_node.active = true;
            this.tips_node.y += 100;
            this.remain_times.string = this._remainTimes;

            this.tengman.node.active = true;
            this.tengman.setAnimation(0, "animation6_1", true);
            let winCoin = cc.find("coin", this.tengman.node);
            winCoin.active = true;
            winCoin.opacity = 255;
            winCoin.getComponent(cc.Label).string = Global.formatNumShort(pickBonus.winCoin);
        });
    },

    async enterPickBonus(posY) {
        return new Promise(async (success) => {
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("pick1_bgm");

            cc.find("role", this.node.parent.parent).active = false;
            this.tengman.node.active = true;

            this.node.active = true;

            this.reset();
            this._successCallback = success;
            this._startPosY = posY;

            this.bonus_bj.node.active = true;
            this.bonus_bj.setAnimation(0, "animation1_1", false);
            this.bonus_bj.addAnimation(0, "animation1_2", true);

            this.bonus_wenzi.node.active = true;
            this.bonus_wenzi.node.y = posY;
            this.bonus_wenzi.setAnimation(0, "animation2", true);
            cc.tween(this.bonus_wenzi.node)
                .to(0.5, {y: 0})
                .start();

            await cc.vv.gameData.awaitTime(0.5);

            this.reels_bg.active = true;
            this.reels_frame.active = true;

            this.items_node.active = true;

            for (let i = 0; i < this.items.length; i++) {
                let item = this.items[i];
                cc.tween(item)
                    .delay(i % 4 * 0.3)
                    .to(0.3, {scale: 1})
                    .start();
            }

            await cc.vv.gameData.awaitTime(1.2);

            let collect_node = cc.find("collect_node", this.node.parent);
            cc.tween(collect_node)
                .by(0.5, {y: -100})
                .start();

            await cc.vv.gameData.awaitTime(0.5);

            this.tips_node.active = true;
            cc.tween(this.tips_node)
                .by(0.5, {y: 100})
                .start();

            this.remain_times.string = this._remainTimes;

            await cc.vv.gameData.awaitTime(0.5);
            this._canSelect = true;

            for (let i = 0; i < this.items.length; i++) {
                let item = this.items[i];
                item.off(cc.Node.EventType.TOUCH_END);
                item.on(cc.Node.EventType.TOUCH_END, () => {
                    if (!this._canSelect) {
                        return;
                    }
                    item.off(cc.Node.EventType.TOUCH_END);

                    cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "pick_click", true);
                    this._canSelect = false;
                    let req = {c: MsgId.SLOT_SUBGAME_DATA};
                    req.uid = Global.playerData.uid;
                    req.gameid = cc.vv.gameData._gameId;
                    req.data = {};
                    req.data.rtype = 2;
                    req.data.choiceId = i + 1;
                    cc.vv.NetManager.send(req);
                });
            }
        });
    },

    reset() {
        this.reels_bg.active = false;
        this.tips_node.y = 116;
        this.reels_frame.active = false;
        this.bonus_bj.node.active = false;
        this.bonus_wenzi.node.active = false;
        this.items_node.active = false;
        for (let item of this.items) {
            cc.find("lanbaoshi", item).active = false;
            cc.find("coin", item).active = false;
            cc.find("pick_more", item).active = false;
            cc.find("jackpot", item).active = false;
            cc.find("dianji", item).active = false;
            cc.find("shoujifei", item).active = false;
            cc.find("zishuijing", item).active = true;
            cc.find("zishuijing", item).getComponent(sp.Skeleton).setAnimation(0, "animation2", true);
            for (let child of item.children) {
                child.color = cc.Color.WHITE;
            }
            item.scale = 0;
        }

        this._successCallback = null;
        this._canSelect = false;
        this._remainTimes = 3;
        this._haveOpenReward = [];
    },

    async onRcvSubGameData(msg) {
        if (msg.code !== 200) {
            this._canSelect = true;
            return;
        }

        if (msg.data.rtype !== 2) {
            return;
        }

        let data = msg.data;
        this._result = data;
        this._haveOpenReward.push(data.choiceId);
        this._remainTimes--;
        if (this._remainTimes < 0) {
            this._remainTimes = 0;
        }
        this.remain_times.string = this._remainTimes;

        if (data.pickBonus.spinCnt === 0) {
            // 结束了
            this.showReward(data.choiceId, false, data.pickBonus.items[data.choiceId - 1], data.pickBonus.winCoin);
            this._canSelect = false;
            this._winCoin = data.pickBonus.winCoin;

            cc.vv.gameData.AddCoin(this._winCoin);

            await cc.vv.gameData.awaitTime(3);

            // cc.vv.AudioManager.playEff("games/SpookyHalloween/", "pick_end", true);

            for (let i = 0; i < this.items.length; i++) {
                if (this._haveOpenReward.indexOf(i + 1) === -1) {
                    this.showReward(i + 1, true, data.pickBonus.items[i], data.pickBonus.winCoin);
                }
            }

            await cc.vv.gameData.awaitTime(2);

            await this.exitPickBonus();
        } else {
            // 没结束
            this.showReward(data.choiceId, false, data.pickBonus.items[data.choiceId - 1], data.pickBonus.winCoin);
        }
    },

    async showReward(choiceId, isGray, reward, allWinCoin) {
        let item = this.items[choiceId - 1];
        let zishuijing = item.getChildByName("zishuijing");
        if (isGray) {
            zishuijing.getComponent(sp.Skeleton).setAnimation(0, "animation1", true);
            for (let child of item.children) {
                child.color = cc.Color.GRAY;
            }
            if (reward.repick) {
                cc.find("pick_more", item).active = true;
            } else if (reward.coin > 0) {
                let coin = cc.find("coin", item);
                coin.active = true;
                coin.getComponent(cc.Label).string = Global.formatNumShort(reward.coin, 0);
            } else if (reward.jackpot) {
                let atlas = cc.vv.gameData.GetAtlasByName("symbols");
                cc.find("jackpot", item).active = true;
                cc.find("jackpot", item).getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme205_s_jp" + (5 - reward.jackpot.id));
            }
        } else {
            let dianji_spine = cc.find("dianji", item).getComponent(sp.Skeleton);
            dianji_spine.node.active = true;
            dianji_spine.setAnimation(0, "animation", false);
            dianji_spine.setCompleteListener(() => {
                dianji_spine.setCompleteListener(null);
                dianji_spine.node.active = false;
            });

            zishuijing.getComponent(sp.Skeleton).setAnimation(0, "animation3", false);

            await cc.vv.gameData.awaitTime(0.5);

            let lanbaoshi_spine = cc.find("lanbaoshi", item).getComponent(sp.Skeleton);
            lanbaoshi_spine.node.active = true;
            lanbaoshi_spine.setAnimation(0, "animation1", true);

            if (reward.repick) {
                cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "pick_addone", true);
                let pick_more = cc.find("pick_more", item);
                pick_more.scale = 0;
                pick_more.active = true;
                cc.tween(pick_more)
                    .to(0.5, {scale: 1})
                    .start();

                await cc.vv.gameData.awaitTime(0.5);

                this._remainTimes++;
                this.pick_lizi.active = true;
                this.pick_lizi.position = item.position;
                let endPos = this.remain_times.node.convertToWorldSpaceAR(cc.v2(0, 0));
                endPos = this.node.convertToNodeSpaceAR(endPos);
                cc.tween(this.pick_lizi)
                    .to(0.5, {position: endPos})
                    .call(() => {
                        this.remain_times.string = this._remainTimes;
                        this.pick_lizi.active = false;
                    })
                    .start();

                await cc.vv.gameData.awaitTime(1.2);

                lanbaoshi_spine.setAnimation(0, "animation2", false);
                lanbaoshi_spine.addAnimation(0, "animation1", true);

                await cc.vv.gameData.awaitTime(0.3);

                pick_more.active = false;
            }

            if (reward.coin > 0) {
                cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "pick_coin", true);
                let coin = cc.find("coin", item);
                coin.active = true;
                coin.scale = 0;
                coin.getComponent(cc.Label).string = Global.formatNumShort(reward.coin, 0);
                cc.tween(coin)
                    .to(0.5, {scale: 1})
                    .call(() => {
                        if (this._haveOpenReward.length === 1) {
                            // 第一次藤蔓需要有动画
                            this.tengman.setAnimation(0, "animation7", false);
                            this.tengman.addAnimation(0, "animation6_1", true);
                        }
                    })
                    .delay(0.2)
                    .call(() => {
                        let shoujifei_spine = cc.find("shoujifei", item).getComponent(sp.Skeleton);
                        shoujifei_spine.node.active = true;
                        shoujifei_spine.setAnimation(0, "animation" + choiceId, false);
                        shoujifei_spine.setCompleteListener(() => {
                            shoujifei_spine.setCompleteListener(null);
                            shoujifei_spine.node.active = false;

                            let winCoin = cc.find("coin", this.tengman.node);
                            winCoin.active = true;
                            winCoin.opacity = 255;
                            winCoin.getComponent(cc.Label).string = Global.formatNumShort(allWinCoin, 0);

                            this._canSelect = true;

                            cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "logo_collect", true);
                            let bonusjieshou_spine = cc.find("bonusjieshou", this.tengman.node).getComponent(sp.Skeleton);
                            bonusjieshou_spine.node.active = true;
                            bonusjieshou_spine.setAnimation(0, "animation", false);
                            bonusjieshou_spine.setCompleteListener(() => {
                                bonusjieshou_spine.setCompleteListener(null);
                                bonusjieshou_spine.node.active = false;
                            })
                        })
                    })
                    .start();
            } else if (reward.jackpot) {
                let jackpot = cc.find("jackpot", item);
                let atlas = cc.vv.gameData.GetAtlasByName("symbols");
                jackpot.active = true;
                jackpot.scale = 0;
                jackpot.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme205_s_jp" + (5 - reward.jackpot.id));
                cc.tween(jackpot)
                    .to(0.5, {scale: 1})
                    .call(() => {
                        if (this._haveOpenReward.length === 1) {
                            // 第一次藤蔓需要有动画
                            this.tengman.setAnimation(0, "animation7", false);
                            this.tengman.addAnimation(0, "animation6_1", true);
                        }
                    })
                    .delay(0.2)
                    .call(() => {
                        let shoujifei_spine = cc.find("shoujifei", item).getComponent(sp.Skeleton);
                        shoujifei_spine.node.active = true;
                        shoujifei_spine.setAnimation(0, "animation" + choiceId, false);
                        shoujifei_spine.setCompleteListener(() => {
                            shoujifei_spine.setCompleteListener(null);

                            let winCoin = cc.find("coin", this.tengman.node);
                            winCoin.active = true;
                            winCoin.opacity = 255;
                            winCoin.getComponent(cc.Label).string = Global.formatNumShort(allWinCoin, 0);

                            this.popJackpotResult(reward.jackpot);
                        })
                    })
                    .start();
            }
        }
    },

    async popJackpotResult(jackpot) {
        let free_dialog = cc.find("free_dialog", this.node.parent.parent);
        free_dialog.active = true;

        let free_bg = cc.find("free_dialog_bg", free_dialog);
        free_bg.opacity = 0;
        free_bg.runAction(cc.fadeTo(0.2, 200));

        let dialog = cc.find("jackpot_node", free_dialog);
        dialog.active = true;

        let freetanchuang_spine = cc.find("freetanchuang", dialog).getComponent(sp.Skeleton);
        freetanchuang_spine.node.active = true;

        let coin = cc.find("coin", dialog);
        coin.scale = 0;
        coin.getComponent(cc.Label).string = "";

        let sound = "dialog_mini_collect";
        switch (jackpot.id) {
            case 1:
                sound = "dialog_mini_collect";
                break;
            case 2:
                sound = "dialog_minor_collect";
                break;
            case 3:
                sound = "dialog_major_collect";
                break;
            case 4:
                sound = "dialog_grand_collect";
                break;
        }
        cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", sound, true);

        freetanchuang_spine.setAnimation(0, "animation" + jackpot.id + "_1", false);
        freetanchuang_spine.addAnimation(0, "animation" + jackpot.id + "_2", true);

        let btn_collect = cc.find("btn_collect", dialog);
        btn_collect.scale = 0;

        await cc.vv.gameData.awaitTime(0.3);

        Global.doRoallNumEff(coin, 0, jackpot.value, 3, null, null, 0, true);
        cc.tween(coin)
            .to(0.2, {scale: 1})
            .start();

        await cc.vv.gameData.awaitTime(0.2);

        cc.tween(btn_collect)
            .to(0.2, {scale: 0.5})
            .start();

        await cc.vv.gameData.awaitTime(0.2);

        btn_collect.off("click");
        let func = async ()=>{
            btn_collect.off("click");
            cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "click", true);
            cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "dialog_retract", true);

            // cc.vv.AudioManager.playEff("games/SpookyHalloween/", "free_dialog_collect_close", true);
            // cc.tween(btn_collect)
            //     .to(0.2, {scale: 0})
            //     .start();

            cc.tween(free_bg)
                .to(0.2, {opacity: 0})
                .start();

            freetanchuang_spine.setAnimation(0, "animation" + jackpot.id + "_3", false);
            freetanchuang_spine.setCompleteListener(() => {
                freetanchuang_spine.setCompleteListener(null);
                dialog.active = false;
                free_dialog.active = false;
                freetanchuang_spine.node.active = false;
                this._canSelect = true;
            });

            await cc.vv.gameData.awaitTime(0.3);

            cc.tween(coin)
                .to(0.2, {scale: 0})
                .start();
        }
        cc.vv.gameData.checkAutoPlay(btn_collect, func);
        btn_collect.on("click", async () => {
            btn_collect.stopAllActions();
            await func();
        });
    },

    async exitPickBonus() {
        this.reels_bg.active = false;
        this.reels_frame.active = false;
        this.items_node.active = false;

        this.bonus_bj.setAnimation(0, "animation1_3", false);
        this.bonus_bj.setCompleteListener(()=>{
            this.bonus_bj.setCompleteListener(null);
            this.bonus_bj.node.active = false;
        });

        cc.tween(this.bonus_wenzi.node)
            .to(0.5, {y: this._startPosY})
            .call(()=>{
                this.bonus_wenzi.node.active = false;
            })
            .start();

        let coin = cc.find("coin", this.tengman.node);
        cc.tween(coin)
            .to(0.5, {opacity: 0})
            .call(()=>{
                coin.active = false;
            })
            .start();

        this.tips_node.y -= 100;
        this.tips_node.active = false;

        cc.tween(cc.find("collect_node", this.node.parent))
            .by(0.5, {y: 100})
            .start();

        this.tengman.setAnimation(0, "animation1", false);
        this.tengman.addAnimation(0, "animation2", true);

        await cc.vv.gameData.awaitTime(1);

        this.tengman.node.active = false;
        cc.find("role", this.node.parent.parent).active = true;

        this.node.active = false;
        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playNormalBgm();
        this._successCallback();
    },

    getWinCoin() {
        return this._winCoin;
    },


});