/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {

    },

    //旋转
    StartMove:function(){
        this._super();

        let bg = cc.find("reels_bg/reel_bg"+(this._reelIdx+1),this.node.parent.parent)
        if(bg){
            bg.color = cc.Color.GRAY;
        }
    },

    //列停止
    OnReelSpinEnd:function(){
        this._super();
    },

    clearLastSymbol() {
        let symbol = this._symbols[this._symbols.length - 1];
        if (symbol) {
            symbol.setAnimationToTop(false);
            symbol.ShowKuang(false);
        }
    },

    playReelStop(){
        let haveSpecialSymbol = false;
        if (this._originResult) {
            for(let i = 0; i < this._originResult.length; i++){
                let item = this._symbols[i]
                if (item.GetShowId() === this._cfg.bonusId ||
                    item.GetShowId() === this._cfg.extraSpinId ||
                    item.GetShowId() === this._cfg.scatterId
                ) {
                    haveSpecialSymbol = true;
                    if (item.GetShowId() === this._cfg.bonusId) {
                        cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "bonus1_land", true);
                    } else if (item.GetShowId() === this._cfg.scatterId) {
                        cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "gemrush_land", true);
                    }
                    else {
                        cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "bonus2_land", true);
                    }
                    item.playStopAnimation();
                }
            }
        }
        if (haveSpecialSymbol) {
            // cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "reel_stop", true);
        } else {
            cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "reel_stop", true);
        }

        let bg = cc.find("reels_bg/reel_bg"+(this._reelIdx+1),this.node.parent.parent)
        if(bg){
            bg.color = cc.Color.WHITE;
        }

        for (let symbol of this._symbols) {
            symbol.resetColor();
        }
    },

    playAntiAnimation(){
        let isPlayAniti = false;
        let gameInfo = cc.vv.gameData.getGameInfo();

        if (this._reelIdx === 4) {
            if (gameInfo.gemsPushBonus) {
                this.ShowAntiEffect(true, "node_anti");
                cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "reel_notify", true);
                this._speed = 2000;
                isPlayAniti = true;
            } else {
                if (Math.random() <= 0.05) {
                    if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
                        return isPlayAniti;
                    }
                    this.ShowAntiEffect(true, "node_anti");
                    cc.vv.AudioManager.playEff("games/MinamotoNoYoshitsune/", "reel_notify", true);
                    this._speed = 2000;
                    isPlayAniti = true;
                }
            }
        }
        return isPlayAniti
    },

    //显示免费游戏加速效果
    //加速框的显示
    ShowAntiEffect:function(bShow,name){
        if (bShow === false) {
            let node = cc.find("node_anti", this.node)
            if(node && node.active){
                node.active = false
                // 既然不是循环的播放，就不需要主动停止
                // 点立即停止的时候需要停止加速音效
                if(this._stopRightNow){
                    cc.vv.AudioManager.stopEffectByName("reel_notify");
                }
            }
        }else{
            let node = cc.find(name,this.node)
            if(node){
                node.active = bShow
            }
            else{
                cc.log("未找到加速节点：mask/node_anti");
            }
        }
    },

    //reel变化尺寸的时候，需要设置高度的节点(y锚点都是0，这样设置长度都是y方向)
    //reel/mask ,
    //reels_bg/bg*,
    GetResizeHeightObjs:function(){
        let objs = []
        let mask = cc.find("mask",this.node)
        if(mask){
            objs.push(mask)
        }

        let bg = cc.find("reels_bg/reel_bg"+(this._reelIdx+1),this.node.parent.parent)
        if(bg){
            objs.push(bg)
        }

        if (this._reelIdx === 0) {
            let left_bg = cc.find("reels_frame/left_bg", this.node.parent.parent);
            if (left_bg) {
                objs.push(left_bg);
            }

            let right_bg = cc.find("reels_frame/right_bg", this.node.parent.parent);
            if (right_bg) {
                objs.push(right_bg);
            }

            for (let i = 1; i < 5; i++) {
                let line = cc.find("reels_frame/line_" + i, this.node.parent.parent);
                if (line) {
                    objs.push(line);
                }
            }

            let black_bg = cc.find("black_bg", this.node.parent.parent);
            if (black_bg) {
                objs.push(black_bg);
            }
        }

        return objs
    },

    //reel变化尺寸的时候，需要移动的节点
    //reels_frame/reel*/frame
    GetResizeMoveingObjs:function(){
        let objs = []

        if (this._reelIdx === 0) {
            let frameTop = cc.find("reels_frame/top_bg",this.node.parent.parent)
            if(frameTop){
                objs.push(frameTop)
            }

            let freegame_tips = cc.find("freegame_tips", this.node.parent.parent);
            if (freegame_tips) {
                objs.push(freegame_tips);
            }
        }

        return objs
    },
});